#include "platform/app_icon.h"

#include <SDL3/SDL.h>

#include <cstddef>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <string>

#include "app_ids.h"

// gd04_icon_data.cpp / gd04_icon_small_data.cpp, generated by CMake (cmake/embed_file.cmake).
extern const unsigned char kGd04IconPng[], kGd04IconSmallPng[];
extern const std::size_t kGd04IconPngSize, kGd04IconSmallPngSize;

namespace {

SDL_Surface* loadIcon(const unsigned char* data = kGd04IconPng, std::size_t size = kGd04IconPngSize) {
    SDL_IOStream* io = SDL_IOFromConstMem(data, size);
    if (!io) return nullptr;
    SDL_Surface* png = SDL_LoadPNG_IO(io, true);
    if (!png) return nullptr;
    SDL_Surface* rgba = SDL_ConvertSurface(png, SDL_PIXELFORMAT_RGBA32);
    SDL_DestroySurface(png);
    return rgba;
}

}  // namespace

void setAppWindowIcon(SDL_Window* window) {
#ifndef __ANDROID__
    if (!window) return;
    if (SDL_Surface* icon = loadIcon()) {
        // The badge's centre for the small sizes (title bar, taskbar): its letters stay readable.
        if (SDL_Surface* small = loadIcon(kGd04IconSmallPng, kGd04IconSmallPngSize)) {
            SDL_AddSurfaceAlternateImage(icon, small);
            SDL_DestroySurface(small);
        }
        SDL_SetWindowIcon(window, icon);
        SDL_DestroySurface(icon);
    }
#else
    (void)window;
#endif
}

SDL_Surface* appIconSurface() { return loadIcon(); }

void installDesktopEntry() {
#if defined(__linux__) && !defined(__ANDROID__)
    namespace fs = std::filesystem;
    if (SDL_getenv("GD04_NO_DESKTOP_ENTRY")) return;
    std::error_code ec;
    const fs::path exe = fs::read_symlink("/proc/self/exe", ec);
    if (ec || !fs::exists(exe.parent_path() / "LICENSE", ec)) return;  // a development build
    const char* xdg = SDL_getenv("XDG_DATA_HOME");
    const char* home = SDL_getenv("HOME");
    if ((!xdg || !*xdg) && (!home || !*home)) return;
    const fs::path data = xdg && *xdg ? fs::path(xdg) : fs::path(home) / ".local" / "share";
    const std::string id = app::kAppId;
    const fs::path icon = data / "icons" / "hicolor" / "256x256" / "apps" / (id + ".png");
    const fs::path entry = data / "applications" / (id + ".desktop");
    std::ostringstream want;
    want << "[Desktop Entry]\nType=Application\nName=" << app::kDisplayName << "\n"
         << "GenericName=Guitar Hero III: Legends of Rock (Xbox 360) on Guitar Dream Engine\n"
         << "Comment=Play Guitar Hero III: Legends of Rock (Xbox 360) from your own disc image\n"
         << "Exec=\"" << exe.string() << "\"\nPath=" << exe.parent_path().string() << "\nIcon=" << id << "\n"
         << "Terminal=false\nCategories=Game;\nStartupWMClass=" << id << "\n";
    std::ifstream have(entry);
    std::stringstream old;
    old << have.rdbuf();
    if (old.str() == want.str() && fs::exists(icon, ec)) return;  // already pointing here
    fs::create_directories(icon.parent_path(), ec);
    fs::create_directories(entry.parent_path(), ec);
    std::ofstream(icon, std::ios::binary).write(reinterpret_cast<const char*>(kGd04IconPng), std::streamsize(kGd04IconPngSize));
    std::ofstream(entry) << want.str();
    SDL_Log("Application menu entry written: %s", entry.string().c_str());
#endif
}
